import{a,b as i,c as n,d as o,e as s,f as r,g as l,h as c,_ as p,i as d,j as h,k as m,l as g,m as u,n as f,o as b,p as y,q as v,r as w,s as k,t as x,u as _,v as T}from"./chunks/image29.iddmixJK.js";import{_ as A,o as C,c as z,ah as P}from"./chunks/framework.3lAyvTsY.js";const q="/projects/JetArm/en/jetarm-orin-nano/assets/image5.Bk-Nlq5P.webp",O="/projects/JetArm/en/jetarm-orin-nano/assets/image15.YcKYq7HO.webp",I="/projects/JetArm/en/jetarm-orin-nano/assets/image30.JKLsu296.webp",U="/projects/JetArm/en/jetarm-orin-nano/assets/image32.Dj6gIcx2.webp",D="/projects/JetArm/en/jetarm-orin-nano/assets/image33.Dgw99hD1.webp",t="/projects/JetArm/en/jetarm-orin-nano/assets/image4.BB8nzSAp.webp",j="/projects/JetArm/en/jetarm-orin-nano/assets/image38.DQxN3rzF.webp",S="/projects/JetArm/en/jetarm-orin-nano/assets/image39.DDQTpamk.webp",M="/projects/JetArm/en/jetarm-orin-nano/assets/image40.Bt-mi4K2.webp",L="/projects/JetArm/en/jetarm-orin-nano/assets/image42.BRb2jxWU.webp",F="/projects/JetArm/en/jetarm-orin-nano/assets/image43.Cy1r2fZN.webp",R="/projects/JetArm/en/jetarm-orin-nano/assets/image44.DOD774Py.webp",N="/projects/JetArm/en/jetarm-orin-nano/assets/image45.CKhwX99X.webp",E="/projects/JetArm/en/jetarm-orin-nano/assets/image46.D2IANU9o.webp",J="/projects/JetArm/en/jetarm-orin-nano/assets/image47.hEuPTwvR.webp",G="/projects/JetArm/en/jetarm-orin-nano/assets/image48.Bp82m5mq.webp",B="/projects/JetArm/en/jetarm-orin-nano/assets/image49.C7nl_H74.webp",Y="/projects/JetArm/en/jetarm-orin-nano/assets/image50.C9niV--R.webp",W="/projects/JetArm/en/jetarm-orin-nano/assets/image51.BwlH1cs1.webp",V="/projects/JetArm/en/jetarm-orin-nano/assets/image52.BT3xyNZI.webp",Z="/projects/JetArm/en/jetarm-orin-nano/assets/image53.B0y5PgCO.webp",K="data:image/png;base64,",X="/projects/JetArm/en/jetarm-orin-nano/assets/image55.DmZWVobK.webp",Q="/projects/JetArm/en/jetarm-orin-nano/assets/image56.BDt6Onpa.webp",H="/projects/JetArm/en/jetarm-orin-nano/assets/image60.B2g0vNTy.webp",$="/projects/JetArm/en/jetarm-orin-nano/assets/image63.ByG40VZf.webp",ee="/projects/JetArm/en/jetarm-orin-nano/assets/image66.DDhJ4IZw.webp",te="/projects/JetArm/en/jetarm-orin-nano/assets/image67.p6ZnYlrB.webp",ae="/projects/JetArm/en/jetarm-orin-nano/assets/image68.BApeNms4.webp",ie="/projects/JetArm/en/jetarm-orin-nano/assets/image70.DIg_AnD5.webp",ne="/projects/JetArm/en/jetarm-orin-nano/assets/image73.DjcLtfOa.webp",oe="/projects/JetArm/en/jetarm-orin-nano/assets/image74.BHMD5HvV.webp",ue=JSON.parse('{"title":"5. ROS1-ROS+Deep Learning Basic Lesson","description":"","frontmatter":{},"headers":[],"relativePath":"docs/5.ROS1_Deep_Learning_Basic_Lesson.md","filePath":"docs/5.ROS1_Deep_Learning_Basic_Lesson.md"}'),se={name:"docs/5.ROS1_Deep_Learning_Basic_Lesson.md"};function re(le,e,ce,pe,de,he){return C(),z("div",null,[...e[0]||(e[0]=[P('<h1 id="_5-ros1-ros-deep-learning-basic-lesson" tabindex="-1">5. ROS1-ROS+Deep Learning Basic Lesson <a class="header-anchor" href="#_5-ros1-ros-deep-learning-basic-lesson" aria-label="Permalink to &quot;5. ROS1-ROS+Deep Learning Basic Lesson&quot;">​</a></h1><h2 id="_5-1-machine-learning-introduction" tabindex="-1">5.1 Machine Learning Introduction <a class="header-anchor" href="#_5-1-machine-learning-introduction" aria-label="Permalink to &quot;5.1 Machine Learning Introduction&quot;">​</a></h2><h3 id="_5-1-1-what-machine-learning-is" tabindex="-1">5.1.1 What &quot;Machine Learning&quot; is <a class="header-anchor" href="#_5-1-1-what-machine-learning-is" aria-label="Permalink to &quot;5.1.1 What &quot;Machine Learning&quot; is&quot;">​</a></h3><p>Machine learning forms the foundation of artificial intelligence and is essential in imbuing machines with intelligent capabilities. It is an interdisciplinary field that draws upon probability theory, statistics, approximation theory, convex analysis, algorithm complexity theory, and other related disciplines.</p><p>In essence, machine learning is concerned with the study of how computers can acquire new knowledge or skills by simulating or implementing human learning behaviors. It involves the reorganization of existing knowledge structures to continuously improve machine performance. From a practical perspective, machine learning involves training models using data and using those models to make predictions.</p><p>For example, AlphaGo was the first artificial intelligence robot to defeat a human professional Go player and become the world champion. The main working principle behind AlphaGo was deep learning, which involves learning the internal laws and representation levels of sample data to extract valuable information.</p><h3 id="_5-1-2-types-of-machine-learning" tabindex="-1">5.1.2 Types of Machine Learning <a class="header-anchor" href="#_5-1-2-types-of-machine-learning" aria-label="Permalink to &quot;5.1.2 Types of Machine Learning&quot;">​</a></h3><p>Machine learning can be broadly categorized into two types: supervised learning and unsupervised learning. The key distinction between these two types lies in whether the machine learning algorithm has prior knowledge of the classification and structure of the dataset.</p><ul><li><strong>Supervised Learning</strong></li></ul><p>Supervised learning involves providing a labeled dataset to the algorithm, where the correct answers are known. The machine learning algorithm uses this dataset to learn how to compute the correct answers. It is the most commonly used type of machine learning.</p><p>For instance, in image recognition, a large dataset of dog pictures can be provided, with each picture labeled as &quot;<strong>dog</strong>&quot;. This labeled dataset serves as the &quot;<strong>correct answer</strong>&quot;. By learning from this dataset, the machine can develop the ability to recognize dogs in new images.</p><ul><li><strong>Unsupervised Learning</strong></li></ul><p>Unsupervised learning involves providing an unlabeled dataset to the algorithm, where the correct answers are unknown. In this type of machine learning, the machine must mine potential structural relationships within the dataset.</p><p>For instance, in image classification, a large dataset of cat and dog pictures can be provided without any labels. Through unsupervised learning, the machine can learn to divide the pictures into two categories: cat pictures and dog pictures.</p><h2 id="_5-2-framework-introduction" tabindex="-1">5.2 Framework Introduction <a class="header-anchor" href="#_5-2-framework-introduction" aria-label="Permalink to &quot;5.2 Framework Introduction&quot;">​</a></h2><p>There are a large variety of machine learning frameworks. Among them, PyTorch, Tensorflow, MXNet and paddlepaddle are common.</p><h3 id="_5-2-1-pytorch" tabindex="-1">5.2.1 Pytorch <a class="header-anchor" href="#_5-2-1-pytorch" aria-label="Permalink to &quot;5.2.1 Pytorch&quot;">​</a></h3><p>PyTorch is a powerful open-source machine learning framework, originally based on the BSD License Torch framework. It supports advanced multidimensional array operations and is widely used in the field of machine learning. PyTorch, built on top of Torch, offers even greater flexibility and functionality. One of its most distinguishing features is its support for dynamic computational graphs and its Python interface.</p><p>In contrast to TensorFlow&#39;s static computation graph, PyTorch&#39;s computation graph is dynamic. This allows for real-time modifications to the graph as computational needs change. Additionally, PyTorch enables developers to accelerate tensor calculations using GPUs, create dynamic computational graphs, and automatically calculate gradients. This makes PyTorch an ideal choice for machine learning tasks that require flexibility, speed, and powerful computing capabilities.</p><h3 id="_5-2-2-tensorflow" tabindex="-1">5.2.2 TensorFlow <a class="header-anchor" href="#_5-2-2-tensorflow" aria-label="Permalink to &quot;5.2.2 TensorFlow&quot;">​</a></h3><p>TensorFlow is a powerful open-source machine learning framework that allows users to quickly construct neural networks and train, evaluate, and save them. It provides an easy and efficient way to implement machine learning and deep learning concepts. TensorFlow combines computational algebra with optimization techniques to make the calculation of many mathematical expressions easier.</p><p>One of TensorFlow&#39;s key strengths is its ability to run on machines of varying sizes and types, including supercomputers, embedded systems, and everything in between. TensorFlow can also utilize both CPU and GPU computing resources, making it an extremely versatile platform. When it comes to industrial deployment, TensorFlow is often the most suitable machine learning framework due to its robustness and reliability. In other words, TensorFlow is an excellent choice for deploying machine learning applications in a production environment.</p><h3 id="_5-2-3-paddlepaddle" tabindex="-1">5.2.3 PaddlePaddle <a class="header-anchor" href="#_5-2-3-paddlepaddle" aria-label="Permalink to &quot;5.2.3 PaddlePaddle&quot;">​</a></h3><p>PaddlePaddle is a cutting-edge deep learning framework developed by Baidu, which integrates years of research and practical experience in deep learning. PaddlePaddle offers a comprehensive set of features, including training and inference frameworks, model libraries, end-to-end development kits, and a variety of useful tool components. It is the first open-source, industry-level deep learning platform to be developed in China, offering rich and powerful features to developers worldwide.</p><p>Deep learning has proven to be a powerful tool in many machine learning applications in recent years. From image recognition and speech recognition to natural language processing, robotics, online advertising, automatic medical diagnosis, and finance, deep learning has revolutionized the way we approach these fields. With PaddlePaddle, developers can harness the power of deep learning to create innovative and cutting-edge applications that meet the needs of users and businesses alike.</p><h3 id="_5-2-4-mxnet" tabindex="-1">5.2.4 MXNet <a class="header-anchor" href="#_5-2-4-mxnet" aria-label="Permalink to &quot;5.2.4 MXNet&quot;">​</a></h3><p>MXNet is a top-tier deep learning framework that supports multiple programming languages, including Python, C++, Scala, R, and more. It features a dataflow graph similar to other leading frameworks like TensorFlow and Theano, as well as advanced features such as robust multi-GPU support and high-level model building blocks comparable to Lasagne and Blocks. MXNet can run on virtually any hardware, including mobile phones, making it a versatile choice for developers.</p><p>MXNet is specifically designed for efficiency and flexibility, with accelerated libraries that enable developers to leverage the full power of GPUs and cloud computing. It also supports distributed computing across dynamic cloud architectures via distributed parameter servers, achieving near-linear scaling with multiple GPUs/CPUs. Whether you&#39;re working on a small-scale project or a large-scale deep learning application, MXNet provides the tools and support you need to succeed.</p><h2 id="_5-3-gpu-acceleration" tabindex="-1">5.3 GPU Acceleration <a class="header-anchor" href="#_5-3-gpu-acceleration" aria-label="Permalink to &quot;5.3 GPU Acceleration&quot;">​</a></h2><h3 id="_5-3-1-gpu-accelerated-computing" tabindex="-1">5.3.1 GPU Accelerated Computing <a class="header-anchor" href="#_5-3-1-gpu-accelerated-computing" aria-label="Permalink to &quot;5.3.1 GPU Accelerated Computing&quot;">​</a></h3><p>A graphics processing unit (GPU) is a specialized micro processor used to process image in personal computers, workstations, game consoles and mobile devices (phone and tablet). Similar to CPU, but CPU is designed to implement complex mathematical and geometric calculations which are essential for graphics rendering.</p><p>GPU-accelerated computing is the employment of a graphics processing unit (GPU) along with a computer processing unit (CPU) in order to accelerate science, analytics, engineering, consumer and cooperation applications. Moreover, GPU can facilitate the applications on various platforms, including vehicles, phones, tablets, drones and robots.</p><h3 id="_5-3-2-comparison-between-gpu-and-cpu" tabindex="-1">5.3.2 Comparison between GPU and CPU <a class="header-anchor" href="#_5-3-2-comparison-between-gpu-and-cpu" aria-label="Permalink to &quot;5.3.2 Comparison between GPU and CPU&quot;">​</a></h3><p>The main difference between CPU and GPU is how they handle the tasks. CPU consists of several cores optimized for sequential processing. While GPU owns a large parallel computing architecture composed of thousands of smaller and more effective cores tailored for multitasking simultaneously.</p><p>GPU stands out for thousands of cores and large amount of high-speed memory, and is initially intended for processing game and computer image. It is adept at parallel computing which is ideal for image processing, because the pixels are relatively independent. And the GPU provides a large number of cores to perform parallel processing on multiple pixels at the same time, but it only improves throughput without alleviating the delay. For example, when receives one message, it will use only one core to tackle this message although it has thousands of cores. GPU cores are usually employed to complete operations related to image processing, which is not universal as CPU.</p><h3 id="_5-3-3-advantage-of-gpu" tabindex="-1">5.3.3 Advantage of GPU <a class="header-anchor" href="#_5-3-3-advantage-of-gpu" aria-label="Permalink to &quot;5.3.3 Advantage of GPU&quot;">​</a></h3><p>GPUs, equipped with multiple cores, are well-suited for large-scale parallel data processing, providing distinct advantages in efficiently handling extensive repetitive tasks, particularly in multimedia processing.</p><p>Consider deep learning, where the neural network designs aim to analyze massive amounts of data swiftly. This aligns with the strength of GPUs in processing vast datasets.</p><p>Additionally, GPU architecture, optimized based on CPU architecture, lacks specialized image processing algorithms. Consequently, beyond the realm of image processing, GPUs find widespread applications in scientific computing, cryptography, numerical analysis, big data processing, financial analysis, and other domains that demand parallel computation.</p><h2 id="_5-4-tensorrt-acceleration" tabindex="-1">5.4 TensorRT Acceleration <a class="header-anchor" href="#_5-4-tensorrt-acceleration" aria-label="Permalink to &quot;5.4 TensorRT Acceleration&quot;">​</a></h2><h3 id="_5-4-1-tensorrt-introduction" tabindex="-1">5.4.1 TensorRT Introduction <a class="header-anchor" href="#_5-4-1-tensorrt-introduction" aria-label="Permalink to &quot;5.4.1 TensorRT Introduction&quot;">​</a></h3><p>TensorRT is a high-performance deep learning inference, includes a deep learning inference optimizer and runtime that delivers low latency and high throughput for inference applications. It is deployed to hyperscale data centers, embedded platforms, or automotive product platforms to accelerate the inference.</p><p>TensoRT supports almost all deep learning frameworks, such as TensorFlow, Caffe, Mxnet and Pytorch. Combing with new NVIDIA GPU, TensorRT can realize swift and effective deployment and inference on almost all frameworks.</p><p>To accelerate deployment inference, multiple methods to optimize the models are proposed, such as model compression, pruning, quantization and knowledge distillation. And we can use the above methods to optimize the models during training, however TensorRT optimize the trained models. It improves the model efficiency through optimizing the network computation graph.</p><p>After the network is trained, you can directly put the model training file into tensorRT without relying on deep learning framework.</p><h3 id="_5-4-2-optimization-methods" tabindex="-1">5.4.2 Optimization Methods <a class="header-anchor" href="#_5-4-2-optimization-methods" aria-label="Permalink to &quot;5.4.2 Optimization Methods&quot;">​</a></h3><img loading="lazy" height="409" width="861" class="common_img" src="'+q+'"><p>TensorRT has the following optimization strategies:</p><p>(1) Precision Calibration</p><p>(2) Layer &amp; Tensor Fusion</p><p>(3) Kernel Auto-Tuning</p><p>(4) Dynamic Tenser Memory</p><p>(5) Multi-Stream Execution</p><ul><li><strong>Precision Calibration</strong></li></ul><p>In the training phase of neural networks across most deep learning frameworks, network tensors commonly employ 32-bit floating-point precision (FP32). Following training, since backward propagation is unnecessary during deployment inference, there is an opportunity to judiciously decrease data precision, for instance, by transitioning to FP16 or INT8. This reduction in data precision has the potential to diminish memory usage and latency, leading to a more compact model size.</p><p>The table below provides an overview of the dynamic range for different precision:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Precision</strong></th><th style="text-align:center;"><strong>Dynamic Range</strong></th></tr></thead><tbody><tr><td style="text-align:center;">FP32</td><td style="text-align:center;">−3.4×1038 ~ +3.4×1038</td></tr><tr><td style="text-align:center;">FP16</td><td style="text-align:center;">−65504 ~- +65504</td></tr><tr><td style="text-align:center;">INT8</td><td style="text-align:center;">−128 ~ +127</td></tr></tbody></table><p>INT8 is limited to 256 distinct numerical values. When INT8 is employed to represent values with FP32 precision, information loss is certain, resulting in a decline in performance. Nevertheless, TensorRT provides a fully automated calibration process to optimally align performance by converting FP32 precision data to INT8 precision, thereby minimizing performance loss.</p><ul><li><strong>Layer &amp; Tensor Fusion</strong></li></ul><p>While CUDA cores efficiently compute tensor operations, a significant amount of time is still spent on the initialization of CUDA cores and read/write operations for each layer&#39;s input/output tensors. This results in GPU resource wastage and creates a bottleneck in memory bandwidth.</p><p>TensorRT optimizes the model structure by horizontally or vertically merging layers, reducing the number of layers and consequently decreasing the required CUDA core count, achieving structural optimization.</p><p>Horizontal merging combines convolution, bias, and activation layers into a unified CBR structure, utilizing only one CUDA core. Vertical merging consolidates layers with identical structures but different weights into a broader layer, also using only one CUDA core.</p><p>Moreover, in cases of multi-branch merging, TensorRT can eliminate concat layers by directing layer outputs to the correct memory address without copying, thereby reducing memory access frequency.</p><ul><li><strong>Kernel Auto-Tuning</strong></li></ul><p>During the inference calculation process, the neural network model utilizes the GPU&#39;s CUDA cores for computation. TensorRT can adjust the CUDA cores based on different algorithms, network models, and GPU platforms, ensuring that the current model can perform computational operations with optimal performance on specific platforms.</p><ul><li><strong>Dynamic Tenser Memory</strong></li></ul><p>During the utilization of each Tensor, TensorRT allocates dedicated GPU memory to prevent redundant memory requests, thereby reducing memory consumption and enhancing the efficiency of memory reuse.</p><ul><li><strong>Multi-Stream Execution</strong></li></ul><p>By leveraging CUDA Streams, parallel computation is achieved for multiple branches of the same input, maximizing the potential for parallel operations.</p><h2 id="_5-5-yolov5-model" tabindex="-1">5.5 Yolov5 Model <a class="header-anchor" href="#_5-5-yolov5-model" aria-label="Permalink to &quot;5.5 Yolov5 Model&quot;">​</a></h2><h3 id="_5-5-1-yolo-model-series-introduction" tabindex="-1">5.5.1 Yolo Model Series Introduction <a class="header-anchor" href="#_5-5-1-yolo-model-series-introduction" aria-label="Permalink to &quot;5.5.1 Yolo Model Series Introduction&quot;">​</a></h3><ul><li><strong>YOLO Series</strong></li></ul><p>YOLO (You Only Look Once) is an one-stage regression algorithm based on deep learning.</p><p>R-CNN series algorithm dominates target detection domain before YOLOv1 is released. It has higher detection accuracy, but cannot achieve real-time detection due to its limited detection speed engendered by its two-stage network structure.</p><p>To tackle this problem, YOLO is released. Its core idea is to redefine target detection as a regression problem, use the entire image as network input, and directly return position and category of Bounding Box at output layer. Compared with traditional methods for target detection, it distinguishes itself in high detection speed and high average accuracy.</p><ul><li><strong>YOLOv5</strong></li></ul><p>YOLOv5 is an optimized version based on previous YOLO models, whose detection speed and accuracy is greatly improved.</p><p>In general, a target detection algorithm is divided into 4 modules, namely input end, reference network, Neck network and Head output end. The following analysis of improvements in YOLOv5 rests on these four modules.</p><p>(1) Input end: YOLOv5 employs Mosaic data enhancement method to increase model training speed and network accuracy at the stage of model training. Meanwhile, adaptive anchor box calculation and adaptive image scaling methods are proposed.</p><p>(2) Reference network: Focus structure and CPS structure are introduced in YOLOv5.</p><p>(3) Neck network: same as YOLOv4, Neck network of YOLOv5 adopts FPN+PAN structure, but they differ in implementation details.</p><p>(4) Head output layer: YOLOv5 inherits anchor box mechanism of output layer from YOLOv4. The main improvement is that loss function GIOU_Loss, and DIOU_nms for prediction box screening are adopted.</p><h3 id="_5-5-2-yolov5-model-structure" tabindex="-1">5.5.2 YOLOv5 Model Structure <a class="header-anchor" href="#_5-5-2-yolov5-model-structure" aria-label="Permalink to &quot;5.5.2 YOLOv5 Model Structure&quot;">​</a></h3><ul><li><strong>Component</strong></li></ul><p>(1) Convolution layer: extract features of the image</p><p>Convolution refers to the effect of a phenomenon, action or process that occurs repeatedly over time, impacting the current state of things. Convolution can be divided into two components: &quot;<strong>volume</strong>&quot; and &quot;<strong>accumulation</strong>&quot;. &quot;<strong>Volume</strong>&quot; involves data flipping, while &quot;<strong>accumulation</strong>&quot; refers to the accumulation of the influence of past data on current data. Flipping the data helps to establish the relationships between data points, providing a reference for calculating the influence of past data on the current data.</p><p>In YOLOv5, the data being processed is typically an image, which is two-dimensional in computer vision. Therefore, the convolution applied is also a two-dimensional convolution, with the aim of extracting features from the image. The convolution kernel is an unit area used for each calculation, typically in pixels. The kernel slides over the image, with the size of the kernel being manually set.</p><p>During convolution, the periphery of the image may remain unchanged or be expanded as needed, and the convolution result is then placed back into the corresponding position in the image. For instance, if an image has a resolution of 6×6, it may be first expanded to a 7×7 image, and then substituted into the convolution kernel for calculation. The resulting data is then refilled into a blank image with a resolution of 6×6.</p><img loading="lazy" height="358" width="1054" class="common_img" src="'+a+'"><img loading="lazy" height="739" width="703" class="common_img" src="'+i+'"><p>(2) Pooling layer: enlarge the features of image</p><p>The pooling layer is an essential part of a convolutional neural network and is commonly used for downsampling image features. It is typically used in combination with the convolutional layer. The purpose of the pooling layer is to reduce the spatial dimension of the feature map and extract the most important features.</p><p>There are different types of pooling techniques available, including global pooling, average pooling, maximum pooling, and more. Each technique has its unique effect on the features extracted from the image.</p><img loading="lazy" height="309" width="701" class="common_img" src="'+n+'"><p>Maximum pooling can extract the most distinctive features from an image, while discarding the remaining ones. For example, if we take an image with a resolution of 6×6 pixels, we can use a 2×2 filter to downsample the image and obtain a new image with reduced dimensions.</p><img loading="lazy" height="789" width="862" class="common_img" src="'+o+'"><p>(3) Upsampling layer: restore the size of an image</p><p>This process is sometimes referred to as &quot;<strong>anti-pooling</strong>&quot;. While upsampling restores the size of the image, it does not fully recover the features that were lost during pooling. Instead, it tries to interpolate the missing information based on the available information.</p><p>For example, let&#39;s consider an image with a resolution of 6×6 pixels. Before upsampling, use 3X3 filter to calculate the original image so as to get the new image.</p><img loading="lazy" height="750" width="787" class="common_img" src="'+s+'"><p>(4) Batch normalization layer: organize data</p><p>It aims to reduce the computational complexity of the model and to ensure that the data is better mapped to the activation function.</p><p>Batch normalization works by standardizing the data within each mini-batch, which reduces the loss of information during the calculation process. By retaining more features in each calculation, batch normalization can improve the sensitivity of the model to the data.</p><img loading="lazy" height="195" width="775" class="common_img" src="'+r+'"><p>(5) RELU layer: activate function</p><p>The activation function is a crucial component in the process of building a neural network, as it helps to increase the nonlinearity of the model. Without an activation function, each layer of the network would be equivalent to a matrix multiplication, and the output of each layer would be a linear function of the input from the layer above. This would result in a neural network that is unable to learn complex relationships between the input and output.</p><p>There are many different types of activation functions. Some of the most common activation functions include the ReLU, Tanh, and Sigmoid. For example, ReLU is a piecewise function that replaces all values less than zero with zero, while leaving positive values unchanged.</p><img loading="lazy" height="392" width="536" class="common_img" src="'+l+'"><p>(6) ADD layer: add tensor</p><p>In a typical neural network, the features can be divided into two categories: salient features and inconspicuous features.</p><img loading="lazy" height="316" width="836" class="common_img" src="'+c+'"><p>(7) Concat layer: splice tensor</p><p>It is used to splice together tensors of features, allowing for the combination of features that have been extracted in different ways. This can help to increase the richness and complexity of the feature set.</p><img loading="lazy" height="599" width="808" class="common_img" src="'+p+'"><ul><li><strong>Compound Element</strong></li></ul><p>When building a model, using only the layers mentioned above to construct functions can lead to lengthy, disorganized, and poorly structured code. By assembling basic elements into various units and calling them accordingly, the efficiency of writing the model can be effectively improved.</p><p>(1) Convolutional unit:</p><p>A convolutional unit consists of a convolutional layer, a batch normalization layer, and an activation function. The convolution is performed first, followed by batch normalization, and finally activated using an activation function.</p><img loading="lazy" height="293" width="821" class="common_img" src="'+O+'"><p>(2) Focus module</p><p>The Focus module for interleaved sampling and concatenation first divides the input image into multiple large regions and then concatenates the small images at the same position within each region to break down the input image into several smaller images. Finally, the images are preliminarily sampled using convolutional units.</p><p>As shown in the figure below, taking an image with a resolution of 6×6 as an example, if we set a large region as 2×2, then the image can be divided into 9 large regions, each containing 4 small images.</p><p>By concatenating the small images at position 1 in each large region, a 3×3 image can be obtained. The small images at other positions are similarly concatenated, and the original 6×6 image will be broken down into four 3×3 images.</p><img loading="lazy" height="418" width="1055" class="common_img" src="'+d+'"><p>(3) Residual unit</p><p>The function of the residual unit is to enable the model to learn small changes in the image. Its structure is relatively simple and is achieved by combining data from two paths.</p><p>The first path uses two convolutional units to sample the image, while the second path does not use convolutional units for sampling but directly uses the original image. Finally, the data from the first path is added to the second path.</p><img loading="lazy" height="287" width="963" class="common_img" src="'+h+'"><img loading="lazy" height="376" width="1060" class="common_img" src="'+m+'"><p>(4) Composite Convolution Unit</p><p>In YOLOv5, the composite convolution unit is characterized by the ability to customize the convolution unit according to requirements. The composite convolution unit is also realized by superimposing data obtained from two paths.</p><p>The first path only has one convolutional layer for sampling, while the second path has 2x+1 convolutional units and one convolutional layer for sampling. After sampling and splicing, the data is organized through batch normalization and then activated by an activation function. Finally, a convolutional layer is used for sampling.&#39;</p><img loading="lazy" height="750" width="522" class="common_img" src="'+g+'"><p>(5) Compound Residual Convolutional Unit</p><p>The compound residual convolutional unit replaces the 2x convolutional layers in the compound convolutional unit with x residual units. In YOLOv5, the feature of the compound residual unit is mainly that the residual units can be customized according to the needs.</p><img loading="lazy" height="750" width="522" class="common_img" src="'+u+'"><p>(6) Composite Pooling Unit</p><p>The output data of the convolutional unit is fed into three max pooling layers and an additional copy is kept without processing. Then, the data from the four paths are concatenated and input into a convolutional unit. Using the composite pooling unit to process the data can significantly enhance the features of the original data.&#39;</p><img loading="lazy" height="705" width="743" class="common_img" src="'+f+'"><ul><li><strong>Structure</strong></li></ul><p>Composed of three parts, YOLOv5 can output three sizes of data. Data of each size is processed in different way. The below picture is the output structure of YOLOv5.</p><img loading="lazy" height="1525" width="1215" class="common_img" src="'+b+'"><p>Below is the output structures of data of three sizes.</p><img loading="lazy" height="1414" width="928" class="common_img" src="'+y+'"><img loading="lazy" height="1536" width="1081" class="common_img" src="'+v+'"><img loading="lazy" height="1710" width="1088" class="common_img" src="'+w+'"><h2 id="_5-6-yolov5-running-procedure" tabindex="-1">5.6 YOLOv5 Running Procedure <a class="header-anchor" href="#_5-6-yolov5-running-procedure" aria-label="Permalink to &quot;5.6 YOLOv5 Running Procedure&quot;">​</a></h2><p>In this section, we provide an explanation of the model workflow using the anchor boxes, prediction boxes, and prior boxes employed in YOLOv5.</p><h3 id="_5-6-1-prior-bounding-box" tabindex="-1">5.6.1 Prior Bounding Box <a class="header-anchor" href="#_5-6-1-prior-bounding-box" aria-label="Permalink to &quot;5.6.1 Prior Bounding Box&quot;">​</a></h3><p>When an image is input into model, object detection area requires us to offer, while prior bounding box is that box used to mark the object detection area on image before detection.</p><img loading="lazy" height="588" width="1039" class="common_img" src="'+k+'"><h3 id="_5-6-2-prediction-box" tabindex="-1">5.6.2 Prediction Box <a class="header-anchor" href="#_5-6-2-prediction-box" aria-label="Permalink to &quot;5.6.2 Prediction Box&quot;">​</a></h3><p>The prediction box is not required to set manually, which is the output result of the model. When the first batch of training data is input into model, the prediction box will be automatically generated with it. The position in which the object of same type appear more frequently are set as the center of the prediction box.</p><img loading="lazy" height="590" width="1039" class="common_img" src="'+x+'"><h3 id="_5-6-3-anchor-box" tabindex="-1">5.6.3 Anchor Box <a class="header-anchor" href="#_5-6-3-anchor-box" aria-label="Permalink to &quot;5.6.3 Anchor Box&quot;">​</a></h3><p>After the prediction box is generated, deviation may occur in its size and position. At this time, the anchor box serves to calibrate the size and position of the prediction box.</p><p>The generation position of anchor box is determined by prediction box. In order to influence the position of the next generation of the prediction box, the anchor box is generated at the relative center of the existing prediction box.</p><img loading="lazy" height="586" width="1039" class="common_img" src="'+_+'"><h3 id="_5-6-4-realization-process" tabindex="-1">5.6.4 Realization Process <a class="header-anchor" href="#_5-6-4-realization-process" aria-label="Permalink to &quot;5.6.4 Realization Process&quot;">​</a></h3><p>After the data is calibrated, a prior bounding box appears on image. Then, the image data is input to the model, the model generates a prediction box based on the position of the prior bounding box. Having generated the prediction box, an anchor box will appear automatically. Lastly, the weights from this training are updated into model.</p><p>Each newly generated prediction will be influenced by the last generated anchor box. Repeating the operations above continuously, the deviation of the size and position of the prediction box will be gradually erased until it coincides with the priori box.</p><img loading="lazy" height="181" width="969" class="common_img" src="'+T+'"><h2 id="_5-7-object-detection-model-training" tabindex="-1">5.7 Object Detection Model Training <a class="header-anchor" href="#_5-7-object-detection-model-training" aria-label="Permalink to &quot;5.7 Object Detection Model Training&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>A wired connection using an Ethernet cable is required during the model training process. Users should prepare an Ethernet cable in advance for connecting the robot.</p></div><h3 id="_5-7-1-image-collecting" tabindex="-1">5.7.1 Image Collecting <a class="header-anchor" href="#_5-7-1-image-collecting" aria-label="Permalink to &quot;5.7.1 Image Collecting&quot;">​</a></h3><p>To effectively train the Yolov5 model, a substantial amount of data is necessary. Thus, it is crucial to collect and annotate data as part of the preparation for the subsequent model training.</p><p>Please begin by preparing the images that need to be collected. To illustrate this process, we can use waste cards as an example.</p><ul><li><strong>Preparation</strong></li></ul><p>The training of image datasets requires a considerable amount of swap space. Since the initial system space may be insufficient, it needs to be reallocated.</p><p>(1) Enter the command &#39;<strong>df -h</strong>&#39; to check the system&#39;s memory space and ensure that the size of the system files is approximately the same as the size of the SD card.</p><img loading="lazy" height="181" width="614" class="common_img" src="'+I+'"><p>If the sizes are not consistent, enter the command &#39;<strong>sudo expand_fs.sh</strong>.&#39; The system will check if expansion is currently in progress; if not, it will extend the system memory to occupy the entire SD card.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo expand_fs.sh</span></span></code></pre></div><ul><li><strong>Create New Dataset Folder</strong></li></ul><p>Create a new folder (e.g., &#39;<strong>My_Data</strong>&#39;—please choose a specific name of your choice; we have already set this up in the system) to store your dataset. To prevent the training process from interfering with the normal use of other files, it is recommended to create the folder under the &#39;Home&#39; path in Files. After entering the command, you should see the newly created folder.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir My_data</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ls</span></span></code></pre></div><img loading="lazy" height="84" width="661" class="common_img" src="'+U+'"><p>(1) Within the newly created &#39;My_Data&#39; folder, create three additional directories: &#39;Annotations&#39; (for storing annotation files), &#39;ImageSets&#39; (for storing dataset path files), and &#39;JPEGImages&#39; (for storing dataset images). After entering the command, you should see three new folders.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir -p My_data/Annotations My_data/ImageSets My_data/JPEGImages</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd My_data</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ls</span></span></code></pre></div><img loading="lazy" height="107" width="662" class="common_img" src="'+D+'"><ul><li><strong>Image Collecting</strong></li></ul><p>(1) Start the robot, and access the robot system desktop using NoMachine.</p><p>(2) Click-on <img loading="lazy" height="71" width="76" src="'+t+'"> to open the command-line terminal. Execute the command below to terminate the app auto-start service.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.stop_ros.sh</span></span></code></pre></div><p>(3) Run the command below to initiate the camera service.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>roslaunch jetarm_peripherals camera.launch</span></span></code></pre></div><p>(4) Double-click <img loading="lazy" height="71" width="76" src="'+t+'"> to open the image collecting tool.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rosrun dataset_capture main.py</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>The model reliability is contingent on having a sufficient quantity of image materials. For instance, when annotating garbage cards, it is recommended to have over 200 images per garbage card for a relatively better performance. The more images available, the better the recognition performance, with the relationship between the final number of images and recognition effectiveness following a curved trend.</p></div><p>(5) In the camera interface, click on &#39;<strong>Select</strong>,&#39; then in the pop-up window, choose &#39;<strong>/home/ubuntu/My_data/JPEGImages</strong>,&#39; and click &#39;<strong>Open</strong>&#39; to save the image materials to that path.</p><img loading="lazy" height="424" width="626" class="common_img" src="'+j+'"><p>(6) Place the cards to be trained within the camera&#39;s field of view, and click &#39;<strong>Save</strong>&#39; each time you capture an image to save the current frame.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>To enhance the reliability of the model, please capture target recognition content from different distances, rotation angles, and tilt angles.</p></li><li><p>For stable recognition, it is advisable to use a significant number of images for training. Specifically, aim for at least 150 images per category when collecting training data.</p></li></ul></div><img loading="lazy" height="407" width="421" class="common_img" src="'+S+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>When saving images, ensure to capture the same image from multiple angles in the following scenarios:</p><ul><li><p>Varied distances.</p></li><li><p>Different angles.</p></li><li><p>Various tilt degrees.</p></li><li><p>Diverse lighting conditions.</p></li><li><p>Different backgrounds (black and white are sufficient).</p></li></ul></div><p>(7) At this point, the &#39;<strong>JPEGImages</strong>&#39; folder within the &#39;<strong>My_Data</strong>&#39; directory will automatically generate the captured images for the dataset.</p><img loading="lazy" height="133" width="851" class="common_img" src="'+M+'"><p>(8) After collecting a sufficient number of images (approximately 70 to 100 images per category), if you wish to exit, click the exit button and press &#39;Ctrl+C&#39; in the terminal to close the camera service.</p><p>(9) Next, proceed to <strong>Image Annotation</strong> for further instructions.</p><ul><li><strong>Image Annotation</strong></li></ul><p>Labeling images is indispensable to functional datasets because It enables training model know what classes are important parts of the image so as to identify those classes in new images.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>the input command should be case sensitive, and the keywords can be complemented using Tab key.</p></div><p>(1) Enter the following command to launch the image labeling tool.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 factory_utils/labelImg/labelImg.py</span></span></code></pre></div><p>(2) Upon opening, click &#39;<strong>Change Save Dir</strong>&#39; first to set the save path for annotation data. Choose &#39;<strong>/home/ubuntu/My_Data/Annotations&#39;</strong> here, and then click &#39;<strong>Open</strong>&#39; to proceed.</p><img loading="lazy" height="511" width="804" class="common_img" src="'+L+'"><img loading="lazy" height="422" width="628" class="common_img" src="'+F+'"><p>(3) Start by clicking &#39;<strong>Open Dir</strong>&#39; to access the folder where we store the images. Choose &#39;<strong>/home/ubuntu/My_Data/JPEGImage</strong>&#39; here, and then click &#39;<strong>Open</strong>&#39; to proceed.</p><img loading="lazy" height="511" width="804" class="common_img" src="'+R+'"><img loading="lazy" height="423" width="628" class="common_img" src="'+N+'"><p>(4) Click &#39;<strong>Create RectBox</strong>&#39; in the left toolbar to establish an annotation box. If you cannot find the corresponding tool, you can click on the location indicated by the red arrow.</p><img loading="lazy" height="397" width="554" class="common_img" src="'+E+'"><p>(5) Move the mouse to the appropriate position, then hold down the left mouse button and drag to create a rectangular box around the training content in the photo. Here, we use a banana card as an example.</p><img loading="lazy" height="393" width="543" class="common_img" src="'+J+'"><p>(6) After releasing the mouse, input the category name of the card in the dialog box that appears, and then click &#39;<strong>OK</strong>.&#39; For example, if it&#39;s a banana card, you can enter &#39;<strong>banana</strong>.&#39;</p><img loading="lazy" height="239" width="665" class="common_img" src="'+G+'"><p>(7) After completing the annotation for one image, click &#39;<strong>Save</strong>&#39; to save, and then continue by clicking &#39;<strong>Next Image</strong>&#39; to annotate the next one.</p><img loading="lazy" height="438" width="556" class="common_img" src="'+B+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Shortcuts can be used during annotation to speed up the process. For example, pressing &#39;D&#39; can switch to the next image, and pressing &#39;W&#39; can create an annotation box.</p></li><li><p>You can also press &#39;Ctrl+V&#39; to paste the annotation box from the previous image, but this method is only suitable for annotating images of the same category. This is because when pasting the annotation box, it will also include the name information of the previous image.</p></li></ul></div><p>(8) Upon completing the annotation of all materials, XML format files with the same names as the image files will be generated inside the &quot;<strong>Annotations</strong>&quot; folder. (Note: For the model to be reliable, a sufficient number of image materials is required—collect 70 to 100 images for each category.)</p><img loading="lazy" height="154" width="807" class="common_img" src="'+Y+'"><p>The function of each icon is as below:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Shortcut Key</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="60" width="144" src="'+W+'"></td><td style="text-align:center;">Ctrl+U</td><td style="text-align:center;">Select the directory where the picture is saved.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="60" width="144" src="'+V+'"></td><td style="text-align:center;">Ctrl+R</td><td style="text-align:center;">Select the directory where the calibration data is saved.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="144" src="'+Z+'"></td><td style="text-align:center;">W</td><td style="text-align:center;">Create annotation box</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="144" src="'+K+'"></td><td style="text-align:center;">Ctrl+S</td><td style="text-align:center;">Save annotation</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="143" src="'+X+'"></td><td style="text-align:center;">A</td><td style="text-align:center;">Switch to the previous image</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="143" src="'+Q+'"></td><td style="text-align:center;">D</td><td style="text-align:center;">Switch to the next image</td></tr></tbody></table><p>(9) After completing the annotation, press &#39;<strong>Ctrl+C</strong>&#39; to close the depth camera service, and close both the camera and the annotation tool.</p><p>(10) Open a new terminal, and execute this command &#39;<strong>cd /My_Data</strong>&#39; and press Enter.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd /My_Data</span></span></code></pre></div><p>(11) Enter the command &#39;<strong>touch classes.names</strong>&#39; and press Enter to create the classes.names file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>touch classes.names</span></span></code></pre></div><p>(12) Execute the command &#39;<strong>vim classes.names</strong>&#39; to access the file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim classes.names</span></span></code></pre></div><p>(13) Click the &#39;<strong>I</strong>&#39; key to enter edit mode and add the class names for target recognition content. When adding multiple class names, each class name should be on a separate line. (The class names must match those used when collecting the images.)</p><img loading="lazy" height="164" width="956" class="common_img" src="'+H+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>The class names added here must match the naming used in the &#39;labelImg&#39; image annotation software.</p></div><p>(14) After input, press <strong>Esc</strong> key, and input &quot;<strong>:wq</strong>&quot; to save and close the file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:wq</span></span></code></pre></div><p>(15) Drag and copy the &#39;<strong>txt_gen.py</strong>&#39; and &#39;<strong>xml2yolo.py</strong>&#39; files from the same directory as this document into the &#39;<strong>My_Data</strong>&#39; folder.</p><p>(16) Enter the command to convert the data format and press Enter.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 xml2yolo.py --data /home/ubuntu/My_data --yaml /home/ubuntu/My_data/data.yaml</span></span></code></pre></div><p>If you see a prompt similar to the image below, the conversion was successful (the image shown is for example purposes only; please refer to the actual number of images).</p><img loading="lazy" height="123" width="807" class="common_img" src="'+$+'"><p>(17) Move to <strong>5.7.2 Model Training</strong> to proceed with learning.</p><h3 id="_5-7-2-model-training" tabindex="-1">5.7.2 Model Training <a class="header-anchor" href="#_5-7-2-model-training" aria-label="Permalink to &quot;5.7.2 Model Training&quot;">​</a></h3><p>(1) Execute the command &#39;<strong>cd yolov5</strong>&#39; to navigate to the yolov5 directory.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd yolov5</span></span></code></pre></div><p>(2) Run the command and hit Enter to train the model.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 train.py --data /home/ubuntu/My_data/data.yaml --weights yolov5s.pt --img 160 --epochs 10 --batch 8</span></span></code></pre></div><p>In the command, &#39;<strong>--img</strong>&#39; represents the image size; &#39;<strong>--batch</strong>&#39; is the number of images per batch; &#39;<strong>--epochs</strong>&#39; denotes the number of training epochs; &#39;<strong>--data</strong>&#39; indicates the path to the dataset, and &#39;<strong>--weights</strong>&#39; specifies the type of network for training. Users can modify the above parameters based on their specific needs. If you aim to improve model reliability, you may increase the number of training epochs, but be aware that this will also increase the training time accordingly.</p><p>(3) The training result is as below.</p><img loading="lazy" height="413" width="1267" class="common_img" src="'+ee+'"><p>(4) The relevant files will be generated in the &#39;<strong>~/yolov5/runs/train/</strong>&#39; folder.</p><img loading="lazy" height="85" width="542" class="common_img" src="'+te+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>If multiple training sessions are conducted, the &#39;exp&#39; folder naming here may vary. For example, it might be modified to &#39;exp2,&#39; &#39;exp3,&#39; etc. Subsequent steps will depend on the folder naming used in this particular step.</p></div><p>(5) Go to <strong>5.7.3 Model Transformation</strong> section for learning.</p><h3 id="_5-7-3-model-transformation" tabindex="-1">5.7.3 Model Transformation <a class="header-anchor" href="#_5-7-3-model-transformation" aria-label="Permalink to &quot;5.7.3 Model Transformation&quot;">​</a></h3><p>After completing the model training, the model files will be located in the path highlighted by the red box in the image below.</p><img loading="lazy" height="805" width="1268" class="common_img" src="'+ae+'"><p>Execute the following command to convert the model.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 export.py --weights /home/ubuntu/yolov5/runs/train/exp4/weights/best.pt --include onnx --img 480 640</span></span></code></pre></div><img loading="lazy" height="519" width="1262" class="common_img" src="'+ie+'"><p>&#39;<strong>--weights /home/ubuntu/yolov5/runs/train/exp4/weights/best.p</strong>t&#39; is the path to the generated .pt model. &#39;--include onnx&#39; converts it to the ONNX model. &#39;--img 480 640&#39; specifies the image dimensions for model inference, with 480 representing the image height and 640 representing the image width.</p><h3 id="_5-7-4-model-invoking" tabindex="-1">5.7.4 Model Invoking <a class="header-anchor" href="#_5-7-4-model-invoking" aria-label="Permalink to &quot;5.7.4 Model Invoking&quot;">​</a></h3><p>(1) Run the following command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd jetarm/src/jetarm_6dof/jetarm_6dof_app/scripts</span></span></code></pre></div><p>(2) Enter the command below:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim yolov5_onnx.py</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>It is recommended to back up this file before making any modifications. If you make a mistake, you can restore the backup; however, if you modify it directly and encounter an error, it may cause other routines to malfunction.</p></div><p>(3) Scroll to the bottom of the document to find the section shown in the image below:</p><img loading="lazy" height="875" width="1267" class="common_img" src="'+ne+'"><p>The first red box highlights the trained model that has been accelerated, located at &#39;<strong>/home/ubuntu/weights/garbage_classification/</strong>&#39;. Users need to modify this based on its naming.</p><p>The second green box indicates the image categories for the trained model. The names entered here must match the order used during model annotation and in the &#39;classes.names&#39; file to avoid errors in model recognition.</p><p>(4) After making the modifications, press &#39;<strong>Esc</strong>&#39; and then enter &#39;<strong>:wq</strong>&#39; to save the changes and exit.</p><p>(5) Run the following command to initiate the target detection.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 yolov5_onnx.py</span></span></code></pre></div><img loading="lazy" height="550" width="648" class="common_img" src="'+oe+'">',277)])])}const fe=A(se,[["render",re]]);export{ue as __pageData,fe as default};
